<script setup>
import { computed, onMounted, ref } from 'vue'
import { api } from '../api'
import { formatDateTime, statusText, zh } from '../localize'
const loading=ref(true),unavailable=ref(false),status=ref(null),statistics=ref(null),weakPoints=ref([]),latestReview=ref(null),latestDigest=ref(null),tasks=ref([]),quizzes=ref([]),memory=ref(null)
const pendingTasks=computed(()=>tasks.value.filter(task=>task.status!=='COMPLETED').slice(0,4))
const recentQuizzes=computed(()=>quizzes.value.slice(0,3))
onMounted(async()=>{try{const base=import.meta.env.VITE_API_BASE_URL||'http://localhost:8080';const response=await fetch(`${base}/api/system/status`);if(!response.ok)throw new Error();status.value=await response.json();[statistics.value,weakPoints.value,latestReview.value,latestDigest.value,tasks.value,quizzes.value,memory.value]=await Promise.all([api.statistics(),api.weakPoints(),api.latestWeeklyReview(),api.latestDigest(),api.tasks(),api.quizzes(),api.memoryStatistics()])}catch{unavailable.value=true}finally{loading.value=false}})
</script>

<template>
  <section class="hero"><div><span class="eyebrow">主动学习</span><h2>欢迎回到 LearnAgent</h2><p>今天多理解一点，明天就离目标更近一步。</p></div><el-tag type="success" effect="light">AI 学习空间</el-tag></section>
  <el-alert v-if="unavailable" type="warning" :closable="false" title="LearnAgent 后端不可用，请启动数据库和后端后刷新。"/>
  <el-skeleton v-else-if="loading" :rows="8" animated/>
  <template v-else>
    <div class="dashboard-metrics"><article><span>待办任务</span><strong>{{statistics.pendingTasks}}</strong><small>保持学习节奏</small></article><article><span>已完成任务</span><strong>{{statistics.completedTasks}}</strong><small>已完成的行动</small></article><article><span>测验正确率</span><strong>{{Math.round(statistics.overallAccuracy*100)}}%</strong><small>共作答 {{statistics.totalQuestionsAnswered}} 题</small></article><article><span>薄弱知识点</span><strong>{{statistics.weakPointCount}}</strong><small>需要重点复习</small></article></div>
    <div class="dashboard-grid">
      <el-card><template #header><div class="card-header"><strong>近期任务</strong><router-link to="/tasks">查看全部</router-link></div></template><div v-if="pendingTasks.length" class="compact-list"><div v-for="task in pendingTasks" :key="task.id"><span class="priority-dot" :class="task.priority.toLowerCase()"/><div><strong>{{zh(task.title)}}</strong><small>{{task.dueAt?formatDateTime(task.dueAt):'无截止时间'}}</small></div><el-tag size="small">{{statusText[task.status]||task.status}}</el-tag></div></div><el-empty v-else description="暂无待办任务，可以创建下一项学习行动。"/></el-card>
      <el-card><template #header><strong>薄弱知识点</strong></template><div v-if="weakPoints.length" class="weak-list"><div v-for="point in weakPoints.slice(0,4)" :key="point.knowledgePoint"><div><strong>{{zh(point.knowledgePoint)}}</strong><small>尝试 {{point.attemptCount}} 次</small></div><el-progress :percentage="Math.round(point.accuracy*100)" :stroke-width="8" :color="point.accuracy<.5?'#e05c68':'#e0a64b'"/></div></div><el-empty v-else description="暂无薄弱知识点，完成一次测验后即可建立学习画像。"/></el-card>
      <el-card><template #header><div class="card-header"><strong>最近测验</strong><router-link to="/quiz">开始练习</router-link></div></template><div v-if="recentQuizzes.length" class="compact-list"><div v-for="quiz in recentQuizzes" :key="quiz.id"><div><strong>{{zh(quiz.title)}}</strong><small>{{zh(quiz.knowledgePoint||'Comprehensive')}} · {{quiz.questions.length}} 题</small></div><el-tag :type="quiz.status==='COMPLETED'?'success':'info'">{{statusText[quiz.status]||quiz.status}}</el-tag></div></div><el-empty v-else description="暂无测验记录。上传课程资料后即可生成练习。"/></el-card>
      <el-card><template #header><div class="card-header"><strong>今日外部资料</strong><router-link v-if="latestDigest" :to="{path:'/workbench',query:{path:latestDigest.markdownPath}}">打开笔记</router-link></div></template><div v-if="latestDigest" class="review-mini"><strong>{{latestDigest.topic}}</strong><span>{{latestDigest.resources.length}} 条可追溯资料</span><p>{{latestDigest.summary}}</p></div><el-empty v-else description="今日资料尚未生成，后台会在08:00自动准备。"/></el-card>
      <el-card><template #header><div class="card-header"><strong>最新学习周报</strong><router-link to="/weekly-review">打开周报</router-link></div></template><div v-if="latestReview" class="review-mini"><strong>完成 {{latestReview.statistics.tasksCompleted}} 项任务 · 作答 {{latestReview.statistics.questionsAnswered}} 题</strong><span>正确率 {{Math.round(latestReview.statistics.overallAccuracy*100)}}%</span><p>{{latestReview.summary||'统计数据已生成。'}}</p></div><el-empty v-else description="暂无学习周报，可生成第一份周报。"/></el-card>
      <el-card><template #header><div class="card-header"><strong>学习项目</strong><router-link to="/workbench">打开工作台</router-link></div></template><div class="review-mini"><strong>把想法变成可执行的项目</strong><span>自由描述 · 自动规划 · 资料整理</span><p>从一个想法开始，让 Agent 帮你生成项目计划、细分任务和学习资料。</p></div></el-card>
      <el-card><template #header><div class="card-header"><strong>记忆巩固</strong><router-link to="/memory">开始复习</router-link></div></template><div v-if="memory" class="memory-mini"><div><strong>{{memory.dueCards}}</strong><span>今日到期卡片</span></div><div><strong>{{Math.min(15,Math.ceil(memory.dueCards*.75))}} 分钟</strong><span>预计复习时间</span></div><div><strong>90%</strong><span>目标留存率</span></div><div><strong>{{memory.highRiskNodes.length}}</strong><span>高遗忘风险知识点</span></div></div><ul v-if="memory?.highRiskNodes.length" class="memory-risk-list"><li v-for="point in memory.highRiskNodes.slice(0,3)" :key="point.name"><span>{{zh(point.name)}}</span><small>风险 {{Math.round(point.forgettingRisk*100)}}%</small></li></ul></el-card>
    </div>
    <div class="readiness-strip"><span>数据库 <b :class="status.databaseConnected?'ready':'off'">{{status.databaseConnected?'就绪':'离线'}}</b></span><span>AI <b :class="status.chatProvider==='CONFIGURED'?'ready':'off'">{{statusText[status.chatProvider]||status.chatProvider}}</b></span><span>向量库 <b :class="status.vectorStore==='READY'?'ready':'off'">{{statusText[status.vectorStore]||status.vectorStore}}</b></span><span>网络搜索 <b :class="status.webSearch==='CONFIGURED'?'ready':'off'">{{statusText[status.webSearch]||status.webSearch}}</b></span></div>
  </template>
</template>
